function CardProgressionEquipmentAttrInfoDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(CardProgressionConstants.NodeNames.Cell)
    local node = GetLuaBehaviour(cell.gameObject, CardProgressionConstants.EnvPath.CardProgressionStarUpPreviewCell)

    ---@type CardProgressionStarUpPreviewCell
    local nodeEnv
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
        nodeEnv = node.Env
    else
        nodeEnv = node.Env
    end
    if nodeEnv then
        local position = index + 1
        local attrId = EquipmentMainAttrs[position]
        local attrData = self._equipmentAttrsDict[attrId] or {}
        local attrVo = CfUtils.GetCfVo(AutoIds.IdSetting46, "AttrDefinesVo", attrId)
        local attrNum = attrData.curAttr or 0
        nodeEnv:FreshUI({
            viewType = CardProgressionConstants.AttrNodeType.Single,
            icon = attrVo.icon,
            name = attrVo.name,
            attrNum = '+' .. attribute_format(attrVo.isConversion, attrNum),
        }, position)
    end

    return cell
end
--endregion handler

